// 通用 split 函数
vector<string> split(const string& str, const string& delimiter) {
    vector<string> result;
    size_t start = 0;
    size_t end = str.find(delimiter);
    while (end != string::npos) {
        result.push_back(str.substr(start, end - start));
        start = end + delimiter.length();
        end = str.find(delimiter, start);
    }
    // 添加最后一个部分
    result.push_back(str.substr(start));
    return result;
}
​
// 递归解决
void dfs(queue<string> &pq, vector<vector<string>> &res, int level) {
    if (res.size() < level) {
        res.push_back({});
    }
    string commment = pq.front();
    pq.pop();
​
    string subComment = pq.front();
    int subCommentCount = stoi(subComment);
​
    pq.pop();
    res[level-1].push_back(commment);
​
    for (int i = 0; i < subCommentCount; i++) {
        dfs(pq, res, level+1);
    }
}
