void printResult(vector<vector<string>> ans) {
    int n = ans.size();
    cout << n << endl;
    for (int i = 0; i < ans.size(); i++) {
        vector<string> tmp = ans[i];
        for (int i = 0; i < tmp.size(); i++) {
            cout << tmp[i];
            if (i != tmp.size() -1) {
                cout << " ";
            }
        }
        cout << endl;
    }
}
