    vector<string> ans = split(s, ",");
    vector<vector<string>> res;
    queue<string> qp;
    for (int i = 0; i < ans.size(); i++) {
        qp.push(ans[i]);
    }
    // 递归构建结果
    while (!qp.empty()) {
        dfs(qp, res, 1);
    }

    // 格式化输出结果
    printResult(res);
​
