public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        scanner.close();
​
        String[] ans = s.split(",");
        List<List<String>> res = new ArrayList<>();
        Queue<String> qp = new LinkedList<>(Arrays.asList(ans));
​
        while (!qp.isEmpty()) {
            dfs(qp, res, 1);
        }
​
        printResult(res);
    }
    // 递归构建结果
    private static void dfs(Queue<String> qp, List<List<String>> res, int level) {
        if (res.size() < level) {
            res.add(new ArrayList<>());
        }
        String comment = qp.poll();
        int subCommentCount = Integer.parseInt(qp.poll());
​
        res.get(level - 1).add(comment);
​
        for (int i = 0; i < subCommentCount; i++) {
            dfs(qp, res, level + 1);
        }
    }
​
    private static void printResult(List<List<String>> ans) {
        System.out.println(ans.size());
        for (List<String> level : ans) {
            System.out.println(String.join(" ", level));
        }
    }
}
