package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
​
// 递归构建结果
func dfs(qp *[]string, res *[][]string, level int) {
    if len(*res) < level {
        *res = append(*res, []string{})
    }
​
    comment := (*qp)[0]
    subCommentCount, _ := strconv.Atoi((*qp)[1])
    *qp = (*qp)[2:]
​
    (*res)[level-1] = append((*res)[level-1], comment)
​
    for i := 0; i < subCommentCount; i++ {
        dfs(qp, res, level+1)
    }
}
​
func printResult(ans [][]string) {
    fmt.Println(len(ans))
    for _, level := range ans {
        fmt.Println(strings.Join(level, " "))
    }
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    input, _ := reader.ReadString('\n')
    input = strings.TrimSpace(input)
​
​
    ans := strings.Split(input, ",")
    res := [][]string{}
    qp := ans
​
    for len(qp) > 0 {
        dfs(&qp, &res, 1)
    }
​
    printResult(res)
}
